const fs = require('fs');
const path = require('path');

const outputDir = path.join(__dirname, 'e2e/assets');
if (!fs.existsSync(outputDir)) {
  fs.mkdirSync(outputDir, { recursive: true });
}

// Minimal valid MP4 file (base64 encoded)
// derived from a 1x1 pixel black h264 video
const minimalMp4Base64 = '';

const buffer = Buffer.from(minimalMp4Base64, 'base64');
fs.writeFileSync(path.join(outputDir, 'small.mp4'), buffer);

console.log('Created e2e/assets/small.mp4');
